def fib(n, memo=None):
    if memo is None:
        memo = {}                # cache of already computed results
    if n <= 1:
        return n                 # base cases, nothing to cache
    if n in memo:
        return memo[n]           # already solved this exact subproblem, reuse it
    memo[n] = fib(n - 1, memo) + fib(n - 2, memo)  # solve once, remember it
    return memo[n]


if __name__ == "__main__":
    n = 10
    print(fib(n))

