def fib(n):
    if n <= 1:
        return n                 # base cases handled directly
    prev, curr = 0, 1            # F(0) and F(1), only two values ever kept
    for _ in range(2, n + 1):
        prev, curr = curr, prev + curr  # slide the window forward by one step
    return curr                  # curr now holds F(n)


if __name__ == "__main__":
    n = 10
    print(fib(n))

