def fib(n):
    # returns the pair (F(k), F(k+1)) for the given k, built from halves of k
    def fib_pair(k):
        if k == 0:
            return (0, 1)                    # F(0) = 0, F(1) = 1
        a, b = fib_pair(k // 2)              # a = F(half), b = F(half + 1)
        c = a * (2 * b - a)                  # doubling identity for F(2 * half)
        d = a * a + b * b                    # doubling identity for F(2 * half + 1)
        if k % 2 == 0:
            return (c, d)                    # k is even: F(k) = c, F(k+1) = d
        else:
            return (d, c + d)                # k is odd: F(k) = d, F(k+1) = c + d
    return fib_pair(n)[0]                    # only F(n) itself is needed


if __name__ == "__main__":
    n = 10
    print(fib(n))

