pair<int, int> fibPair(int k) {
    // returns the pair (F(k), F(k+1)) for the given k, built from halves of k
    if (k == 0) {
        return {0, 1};                          // F(0) = 0, F(1) = 1
    }
    auto [a, b] = fibPair(k / 2);                // a = F(half), b = F(half + 1)
    int c = a * (2 * b - a);                     // doubling identity for F(2 * half)
    int d = a * a + b * b;                       // doubling identity for F(2 * half + 1)
    if (k % 2 == 0) {
        return {c, d};                           // k is even: F(k) = c, F(k+1) = d
    } else {
        return {d, c + d};                       // k is odd: F(k) = d, F(k+1) = c + d
    }
}

int fib(int n) {
    return fibPair(n).first;                     // only F(n) itself is needed
}

